-- PostgreSQL (Neon). Datas preservadas como TEXT no formato UTC do SQLite.
CREATE TABLE IF NOT EXISTS usuario (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome TEXT NOT NULL, email TEXT NOT NULL, senha_hash TEXT NOT NULL, papel TEXT NOT NULL DEFAULT 'OPERADOR' CHECK (papel IN ('ADMINISTRADOR','GESTOR','OPERADOR')), ativo INTEGER NOT NULL DEFAULT 1 CHECK (ativo IN (0,1)), criado_em TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS'));
CREATE UNIQUE INDEX IF NOT EXISTS usuario_email_ci ON usuario(lower(email));
CREATE TABLE IF NOT EXISTS categoria (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS categoria_nome_ci ON categoria(lower(nome));
CREATE TABLE IF NOT EXISTS fornecedor (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome TEXT NOT NULL, telefone TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', prazo_entrega_dias INTEGER NOT NULL DEFAULT 7 CHECK (prazo_entrega_dias >= 1), ativo INTEGER NOT NULL DEFAULT 1 CHECK (ativo IN (0,1)));
CREATE UNIQUE INDEX IF NOT EXISTS fornecedor_nome_ci ON fornecedor(lower(nome));
CREATE TABLE IF NOT EXISTS produto (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sku TEXT NOT NULL, nome TEXT NOT NULL, categoria_id INTEGER NOT NULL REFERENCES categoria(id) ON DELETE RESTRICT, unidade TEXT NOT NULL DEFAULT 'unidade', preco_venda_centavos INTEGER NOT NULL CHECK (preco_venda_centavos >= 0), quantidade_atual INTEGER NOT NULL DEFAULT 0 CHECK (quantidade_atual >= 0), estoque_minimo INTEGER NOT NULL DEFAULT 0 CHECK (estoque_minimo >= 0), fornecedor_id INTEGER REFERENCES fornecedor(id) ON DELETE SET NULL, ativo INTEGER NOT NULL DEFAULT 1 CHECK (ativo IN (0,1)), criado_em TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS'), atualizado_em TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS'));
CREATE UNIQUE INDEX IF NOT EXISTS produto_sku_ci ON produto(lower(sku));
CREATE INDEX IF NOT EXISTS idx_produto_nome ON produto(nome);
CREATE INDEX IF NOT EXISTS idx_produto_categoria ON produto(categoria_id);
CREATE TABLE IF NOT EXISTS movimentacao (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, produto_id INTEGER NOT NULL REFERENCES produto(id) ON DELETE RESTRICT, tipo TEXT NOT NULL CHECK (tipo IN ('ENTRADA','SAIDA')), motivo TEXT NOT NULL, quantidade INTEGER NOT NULL CHECK (quantidade >= 1), valor_unitario_centavos INTEGER CHECK (valor_unitario_centavos IS NULL OR valor_unitario_centavos >= 0), saldo_apos INTEGER NOT NULL CHECK (saldo_apos >= 0), observacao TEXT NOT NULL DEFAULT '', usuario_id INTEGER REFERENCES usuario(id) ON DELETE SET NULL, data TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS'), CHECK ((tipo = 'ENTRADA' AND motivo IN ('COMPRA','DEVOLUCAO_CLIENTE','AJUSTE_POSITIVO','ESTOQUE_INICIAL')) OR (tipo = 'SAIDA' AND motivo IN ('VENDA','PERDA','AJUSTE_NEGATIVO','DEVOLUCAO_FORNECEDOR'))));
CREATE INDEX IF NOT EXISTS idx_mov_produto_data ON movimentacao(produto_id,data);
CREATE INDEX IF NOT EXISTS idx_mov_tipo_motivo_data ON movimentacao(tipo,motivo,data);
CREATE TABLE IF NOT EXISTS recomendacao (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, produto_id INTEGER NOT NULL REFERENCES produto(id) ON DELETE CASCADE, nivel TEXT NOT NULL CHECK (nivel IN ('CRITICO','ATENCAO')), status TEXT NOT NULL DEFAULT 'PENDENTE' CHECK (status IN ('PENDENTE','ACEITA','IGNORADA','EXPIRADA')), quantidade_sugerida INTEGER NOT NULL DEFAULT 0, saldo_no_calculo INTEGER NOT NULL DEFAULT 0, media_diaria DOUBLE PRECISION NOT NULL DEFAULT 0, dias_cobertura DOUBLE PRECISION, tendencia_percentual DOUBLE PRECISION, acao_sugerida TEXT NOT NULL DEFAULT '', justificativa TEXT NOT NULL DEFAULT '', gerada_em TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS'), decidida_em TEXT, decidida_por_id INTEGER REFERENCES usuario(id) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS idx_rec_status_nivel ON recomendacao(status,nivel);
CREATE INDEX IF NOT EXISTS idx_rec_produto ON recomendacao(produto_id);
-- Funções equivalentes ao SQLite, sem exigir extensões no Neon.
CREATE OR REPLACE FUNCTION sem_acento(t TEXT) RETURNS TEXT LANGUAGE SQL IMMUTABLE PARALLEL SAFE AS $$ SELECT translate(lower(t), 'áàâãäéèêëíìîïóòôõöúùûüçñ', 'aaaaaeeeeiiiiooooouuuucn') $$;
CREATE OR REPLACE FUNCTION casefold(t TEXT) RETURNS TEXT LANGUAGE SQL IMMUTABLE PARALLEL SAFE AS $$ SELECT lower(t) $$;
CREATE OR REPLACE FUNCTION impedir_movimentacao() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Movimentações são imutáveis'; END $$;
DROP TRIGGER IF EXISTS trg_mov_sem_update ON movimentacao;
CREATE TRIGGER trg_mov_sem_update BEFORE UPDATE ON movimentacao FOR EACH ROW EXECUTE FUNCTION impedir_movimentacao();
DROP TRIGGER IF EXISTS trg_mov_sem_delete ON movimentacao;
CREATE TRIGGER trg_mov_sem_delete BEFORE DELETE ON movimentacao FOR EACH ROW EXECUTE FUNCTION impedir_movimentacao();
